// Build date range: last 7 days
const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
return [
  {
    json: {
      since: since.toISOString(),
      until: now.toISOString(),
      repo: $vars.GITHUB_REPO || 'owner/repo',
      language: $vars.SUMMARY_LANGUAGE || 'EN'
    }
  }
];

const since = new Date($('Build Date Range').item.json.since);
const until = new Date($('Build Date Range').item.json.until);
const language = $('Build Date Range').item.json.language || 'EN';
const repo = $('Build Date Range').item.json.repo;

// Process commits
const allCommits = $('Fetch Commits').all();
const commits = allCommits[0].json;
const commitSummaries = Array.isArray(commits)
  ? commits.slice(0, 20).map(c => `- ${c.commit?.message?.split('\n')[0] || ''} (@${c.author?.login || 'unknown'})`).join('\n')
  : 'No commits found.';

// Process closed issues (not PRs)
const allIssues = $('Fetch Closed Issues').all();
const issues = Array.isArray(allIssues[0].json) ? allIssues[0].json.filter(i => !i.pull_request) : [];
const issueSummaries = issues.slice(0, 15).map(i => `- #${i.number}: ${i.title} (closed by @${i.closed_by?.login || 'unknown'})`).join('\n') || 'None.';

// Process merged PRs
const allPRs = $('Fetch Merged PRs').all();
const prs = Array.isArray(allPRs[0].json) ? allPRs[0].json.filter(p => p.merged_at && new Date(p.merged_at) >= since) : [];
const prSummaries = prs.slice(0, 15).map(p => `- #${p.number}: ${p.title} (merged by @${p.merged_by?.login || 'unknown'})`).join('\n') || 'None.';

const langInstruction = language === 'FR'
  ? 'Réponds en français.'
  : 'Reply in English.';

const prompt = `You are a tech lead summarizing the past week of development on the GitHub repo: ${repo}.

Date range: ${since.toDateString()} – ${until.toDateString()}

## Commits this week (up to 20):
${commitSummaries}

## Closed Issues:
${issueSummaries}

## Merged Pull Requests:
${prSummaries}

Write a warm, readable narrative summary (3–5 paragraphs) suitable for sharing in a team Slack/email. Highlight the most impactful work, any recurring themes, and shout out contributors. ${langInstruction}`;

return [{ json: { prompt, repo, since: since.toDateString(), until: until.toDateString(), commitCount: Array.isArray(commits) ? commits.length : 0, prCount: prs.length, issueCount: issues.length } }];

const claudeResponse = $json;
const summary = claudeResponse.content?.[0]?.text || 'No summary generated.';
const meta = $('Build Claude Prompt').item.json;

const subject = `📊 Weekly Dev Summary — ${meta.repo} (${meta.since} – ${meta.until})`;
const body = `${summary}\n\n---\n📌 Stats this week: ${meta.commitCount} commits · ${meta.prCount} merged PRs · ${meta.issueCount} issues closed`;

return [{ json: { subject, body, summary, ...meta } }];

